import json,os,datetime
B=os.path.expanduser('~/mnt/Volumes--Caloggero/piattaforma-quiz/casi-free/')
FONTE=lambda soggetto:{"archivio":"The Cancer Imaging Archive (TCIA)","collezione":"NLST (National Lung Screening Trial)","soggetto":soggetto,"doi":"10.7937/TCIA.HMQ8-J677","licenza":"CC BY 4.0","licenza_url":"https://creativecommons.org/licenses/by/4.0/","citazione":"National Lung Screening Trial Research Team (2013). Data from the National Lung Screening Trial (NLST) [Data set]. The Cancer Imaging Archive. https://doi.org/10.7937/TCIA.HMQ8-J677. Dati clinici: sottoinsieme pubblico NLST (CC BY 4.0).","url":"https://www.cancerimagingarchive.net/collection/nlst/"}
OGGI=datetime.datetime.now().strftime('%Y-%m-%d %H:%M')
def salva(n,c,serie_ord=None,descr=None):
    d=B+f'caso-tcia-{n}/'
    s=json.load(open(d+'serie.json'))
    if serie_ord: s=[s[i] for i in serie_ord]
    if descr:
        for x,(t,eta) in zip(s,descr): x['descrizione']=t; x['eta']=eta
    json.dump(s,open(d+'serie.json','w'),ensure_ascii=False,indent=1)
    c['id']=f'caso-tcia-{n}'; c['visibile']=False; c['aggiornato']=OGGI
    json.dump(c,open(d+'caso.json','w'),ensure_ascii=False,indent=1)
    print('scritto',n)

